INSERT INTO public.checklist_requirement_rule (
    id, module_code, requirement_type, title, description, 
    input_schema, show_if, inherit_from, sync_to_parent, 
    min_responses_required, is_mandatory, display_order, local_vernacular
) VALUES
('AGM_RECOMMENDATION', 'LAND_ACQ_PROPOSAL', 'document', 'Recommendation of the Area General Manager', NULL, NULL, '{ "acqModeId": [1, 6, 2] }'::jsonb, NULL, NULL, 1, true, 0, 'क्षेत्रीय महाप्रबंधक की संस्तुति/सिफारिश'),
('COPIES_RELEVANT_PAGES_APPROVED', 'LAND_ACQ_PROPOSAL', 'boolean', 'Copies of relevant pages of approved PR/ Scheme/ Conceptual Report of the Mine/ Project', NULL, NULL, '{ "acqModeId": [2, 6, 1] }'::jsonb, NULL, NULL, 1, true, 10, 'खदान/परियोजना की स्वीकृत पीआर (PR)/योजना/वैचारिक रिपोर्ट के प्रासंगिक पृष्ठों की प्रतियां'),
('CLEARANCE_DGMS', 'LAND_ACQ_PROPOSAL', 'document', 'Copies of statutory clearances like approval obtained from DGMS etc., if obtained', NULL, NULL, '{ "acqModeId": [6, 1, 2] }'::jsonb, NULL, NULL, 1, true, 20, 'वैधानिक मंजूरी की प्रतियां जैसे डीजीएमएस (DGMS) आदि से प्राप्त अनुमोदन, यदि प्राप्त हो'),
('NOTI_SEC_7', 'LAND_ACQ_PROPOSAL', 'document', 'Application requesting MOC for issue of Gazette notification under section 7(1) giving details of coal block.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 30, 'कोयला ब्लॉक का विवरण देते हुए धारा 7(1) के तहत राजपत्र अधिसूचना जारी करने के लिए एमओसी (MOC) से अनुरोध करने वाला आवेदन।'),
('TWO_FILE_UPLOAD_SECTION', 'LAND_ACQ_PROPOSAL', 'document', 'Two file upload section 1) Hindi Format No. 2D  2) English Format No. 2D', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 40, 'दो फाइल अपलोड अनुभाग: 1) हिंदी प्रारूप संख्या 2D 2) अंग्रेजी प्रारूप संख्या 2D'),
('CERTIFICATE_CONFIRMING_THAT_PLANS', 'LAND_ACQ_PROPOSAL', 'document', 'Certificate confirming that the Plans & Schedules have been prepared on the basis of land records of the State Revenue Authority. (Specimen of the certificate is given at Format No.1C)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 50, 'प्रमाणपत्र जो यह पुष्टि करता है कि योजनाएं और अनुसूचियां राज्य राजस्व प्राधिकरण के भूमि अभिलेखों के आधार पर तैयार की गई हैं। (प्रमाणपत्र का नमूना प्रारूप संख्या 1C पर दिया गया है)'),
('NOTI_SEC_7_1', 'LAND_ACQ_PROPOSAL', 'document', 'Certificate confirming that the area proposed to be notified under section 7(1) is the same or within the boundary of the area notified under section 4(1). (Specimen of the certificate is given at Format No.2B)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 60, 'प्रमाणपत्र जो यह पुष्टि करता है कि धारा 7(1) के तहत अधिसूचित किए जाने वाला प्रस्तावित क्षेत्र वही है या धारा 4(1) के तहत अधिसूचित क्षेत्र की सीमा के भीतर है। (प्रमाणपत्र का नमूना प्रारूप संख्या 2B पर दिया गया है)'),
('REHABILITATION_PAFS_ARE_INVOLVED', 'LAND_ACQ_PROPOSAL', 'boolean', 'If Rehabilitation of PAFs are involved then, whether actions for socio-economic study/ census of the project affected families within two months of the notification u/s 7 date have been taken', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 70, 'यदि PAFs का पुनर्वास शामिल है, तो क्या धारा 7 के तहत अधिसूचना की तारीख से दो महीने के भीतर परियोजना प्रभावित परिवारों के सामाजिक-आर्थिक अध्ययन/जनगणना के लिए कार्रवाई की गई है'),
('WEATHER_SATELLITE_IMAGES_ACQUIRED', 'LAND_ACQ_PROPOSAL', 'boolean', 'Weather satellite images of the acquired area have been captured?', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 80, 'क्या अधिग्रहित क्षेत्र की सैटेलाइट तस्वीरें (Weather satellite images) ली गई हैं?'),
('NOTI_SEC_9', 'LAND_ACQ_PROPOSAL', 'boolean', 'Submit all documents required for Notification under section 9 to General Manager (LRE).', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 90, 'धारा 9 के तहत अधिसूचना के लिए आवश्यक सभी दस्तावेज महाप्रबंधक (LRE) को जमा करें।'),
('SEND_ONE_ORIGINAL_COPY', 'LAND_ACQ_PROPOSAL', 'boolean', 'Send one original copy and one photocopy of the above newspaper publications to the General Manager (LRE).', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 100, 'उपरोक्त समाचार पत्र प्रकाशनों की एक मूल प्रति और एक फोटोकॉपी महाप्रबंधक (LRE) को भेजें।'),
('NOTI_SEC_11', 'LAND_ACQ_PROPOSAL', 'boolean', 'Submit all documents required for Notification under section 11 to General Manager (LRE).', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 110, 'धारा 11 के तहत अधिसूचना के लिए आवश्यक सभी दस्तावेज महाप्रबंधक (LRE) को जमा करें।'),
('PASTE_COPIES_NOTIFICATION_U', 'LAND_ACQ_PROPOSAL', 'boolean', 'Paste copies of Notification u/s 11 along with the schedule of land as notified u/s 9 at Panchayet Bhawnas and at other conspicuous places in the mouzas where the acquisition has taken place.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 120, 'धारा 11 के तहत अधिसूचना की प्रतियों को धारा 9 के तहत अधिसूचित भूमि की अनुसूची के साथ पंचायत भवनों और उन मौजाओं में अन्य प्रमुख स्थानों पर चिपकाएं जहां अधिग्रहण हुआ है।'),
('PROCLAIM_SAME_NEARBY_AREAS', 'LAND_ACQ_PROPOSAL', 'boolean', 'Proclaim the same in nearby areas/villages by the beat of drum.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 130, 'आस-पास के क्षेत्रों/गांवों में ढोल पीटकर (मुनादी द्वारा) इसकी घोषणा करें।'),
('SCHEDULE_LAND_TABULAR_FORM', 'LAND_ACQ_PROPOSAL', 'document', 'Schedule of land in tabular form with land type-wise and mouza-wise abstract', NULL, NULL, '{ "acqModeId": [1, 6, 2] }'::jsonb, NULL, NULL, 1, true, 140, 'भूमि प्रकार-वार और मौजा-वार सारांश के साथ सारणीबद्ध रूप में भूमि की अनुसूची'),
('CERT_RECONCILIATION', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of reconciliation certificate (Form VII)', NULL, NULL, '{ "acqModeId": [1, 6, 2] }'::jsonb, NULL, NULL, 1, true, 150, 'समाधान प्रमाण पत्र की प्रति (Form VII)'),
('CLEARANCE_FOREST', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of Forest Clearance, if obtained', NULL, NULL, '{ "acqModeId": [1, 6, 2] }'::jsonb, NULL, NULL, 1, true, 160, 'वन मंजूरी की प्रति, यदि प्राप्त हो'),
('CERT_FIVE_POINT', 'LAND_ACQ_PROPOSAL', 'document', 'A FIVE-POINT certificate in Form XVI', NULL, NULL, '{ "acqModeId": [1, 6, 2] }'::jsonb, NULL, NULL, 1, true, 170, 'फॉर्म XVI में पांच-बिंदु (FIVE-POINT) प्रमाण पत्र'),
('STANDARD_CHECK_LIST_CIRCULATED', 'LAND_ACQ_PROPOSAL', 'document', 'A standard Check List as circulated through Office Order (Ref. No. ECL/CMD/LRE/ANG/Check-list/1071 Date 25th Nov 2005)', NULL, NULL, '{ "acqModeId": [1, 6, 2] }'::jsonb, NULL, NULL, 1, true, 180, 'कार्यालय आदेश (संदर्भ संख्या ECL/CMD/LRE/ANG/Check-list/1071 दिनांक 25 नवंबर 2005) के माध्यम से परिचालित एक मानक चेक लिस्ट'),
('CALCULATION_SHEET_SHOWING_COST', 'LAND_ACQ_PROPOSAL', 'document', 'Calculation sheet showing the cost of land acquisition', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 190, 'भूमि अधिग्रहण की लागत दर्शाने वाली गणना पत्रक'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATION', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Government land/ Patta Land like copy of Government certified market value/ demand of District Authority etc.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 200, 'सरकारी भूमि/पट्टा भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे सरकार द्वारा प्रमाणित बाजार मूल्य की प्रति/जिला प्राधिकरण की मांग आदि।'),
('CALCULATION_SHEET_SHOWING_COST_1', 'LAND_ACQ_PROPOSAL', 'document', 'Calculation sheet showing cost of land acquisition', NULL, NULL, '{ "acqModeId": [2] }'::jsonb, NULL, NULL, 1, true, 210, 'भूमि अधिग्रहण की लागत दर्शाने वाली गणना पत्रक'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATIO_1', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Government land/ Patta Land like a copy of Government certified market value/ demand of District Authority etc.', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 220, 'सरकारी भूमि/पट्टा भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे सरकार द्वारा प्रमाणित बाजार मूल्य की प्रति/जिला प्राधिकरण की मांग आदि।'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATIO_2', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Forest land like copy of demand of State Forest department etc.', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 230, 'वन भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे राज्य वन विभाग की मांग की प्रतियां आदि।'),
('COPY_GOVERNMENT_NOTIFIED_MARKET', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of Government notified market price of tenancy lands for registration cost calculation.', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 240, 'पंजीकरण लागत गणना के लिए किरायेदारी भूमि के सरकारी अधिसूचित बाजार मूल्य की प्रति।'),
('MINUTES_MEETING_HELD_LANDOWNERS', 'LAND_ACQ_PROPOSAL', 'document', 'Minutes of meeting, if held, with landowners for their acceptance with respect to the proposed rate', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 250, 'प्रस्तावित दर के संबंध में उनकी स्वीकृति के लिए भूस्वामियों के साथ बैठक का कार्यवृत्त (यदि आयोजित की गई हो)'),
('COPY_APPROVAL_DISTRICT_AUTHORITY', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of approval of District Authority for purchase of Tribal Land', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 260, 'आदिवासी भूमि की खरीद के लिए जिला प्राधिकरण के अनुमोदन की प्रति'),
('CERTIFICATE_CONFIRMING_THAT_PLANS_1', 'LAND_ACQ_PROPOSAL', 'document', 'Certificate confirming that the Plans or village Schedules have been prepared on the basis of Survey of India Toposheet/ Revenue plan. (Specimen of the certificate is given at Format No.1C)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 270, 'प्रमाणपत्र जो यह पुष्टि करता है कि योजनाएं और अनुसूचियां राज्य राजस्व प्राधिकरण के भूमि अभिलेखों के आधार पर तैयार की गई हैं। (प्रमाणपत्र का नमूना प्रारूप संख्या 1C पर दिया गया है)'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATIO_3', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Forest land like copies of demands of State Forest department etc.', NULL, NULL, '{ "acqModeId": [2] }'::jsonb, NULL, NULL, 1, true, 280, 'वन भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे राज्य वन विभाग की मांग की प्रतियां आदि।'),
('NOTI_SEC_7_2', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of Notification under section 7', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 290, 'धारा 7 के तहत अधिसूचना की प्रति'),
('NOTI_SEC_9_1', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of Notification under section 9', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 300, 'धारा 9 के तहत अधिसूचना की प्रति'),
('COPY_BOARD_APPROVAL', 'LAND_ACQ_PROPOSAL', 'document', 'A copy of the Board approval', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 310, 'बोर्ड के अनुमोदन की एक प्रति'),
('NOTI_SEC_9_2', 'LAND_ACQ_PROPOSAL', 'document', 'Application requesting MOC for issue of Gazette notification under section 9(1) giving details of coal block and copy of section 4(1) and 7(1) notification of the coal block.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 320, 'कोयला ब्लॉक का विवरण देते हुए धारा 9(1) के तहत राजपत्र अधिसूचना जारी करने के लिए एमओसी से आवेदन अनुरोध और कोयला ब्लॉक की धारा 4(1) और 7(1) अधिसूचना की प्रति।'),
('NOTI_SEC_11_1', 'LAND_ACQ_PROPOSAL', 'document', 'Application requesting MOC for issue of Gazette notification under section 11(1)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 330, 'धारा 11(1) के तहत राजपत्र अधिसूचना जारी करने के लिए एमओसी से अनुरोध करने वाला आवेदन'),
('NOTI_SEC_11_2', 'LAND_ACQ_PROPOSAL', 'document', 'A draft order under Section 11(1) of the CBA Act in respect of the coal block / area in English and in Hindi (both hard copy as well as soft copy). (Specimen of the draft notification is given at Format No . 4A)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 340, 'कोयला ब्लॉक/क्षेत्र के संबंध में सीबीए अधिनियम की धारा 11(1) के तहत अंग्रेजी और हिंदी में एक मसौदा आदेश (हार्ड कॉपी और सॉफ्ट कॉपी दोनों)। (मसौदा अधिसूचना का नमूना प्रारूप संख्या 4A पर दिया गया है)'),
('REHABILITATION_PAF_INVOLVED', 'LAND_ACQ_PROPOSAL', 'boolean', 'If rehabilitation of PAF is involved', NULL, NULL, '{ "acqModeId": [2] }'::jsonb, NULL, NULL, 1, true, 350, 'यदि PAF का पुनर्वास शामिल है'),
('NO_OBJECTION_CERTIFICATE_FROM', 'LAND_ACQ_PROPOSAL', 'boolean', 'Whether ‘no objection certificate’ from Coal Controller has been issued', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 360, 'क्या कोयला नियंत्रक (Coal Controller) से ''अनापत्ति प्रमाण पत्र'' (NOC) जारी किया गया है'),
('QUANTUM_LAND_BE_ACQUIRED', 'LAND_ACQ_PROPOSAL', 'boolean', 'Whether the Quantum of land to be acquired is within the limit approved in the Project Report/ Scheme/ Conceptual report of the Mine/ Project', NULL, NULL, '{ "acqModeId": [1, 6, 2] }'::jsonb, NULL, NULL, 1, true, 370, 'क्या अधिग्रहित की जाने वाली भूमि की मात्रा खदान/परियोजना की परियोजना रिपोर्ट/योजना/वैचारिक रिपोर्ट में स्वीकृत सीमा के भीतर है'),
('INVOLVEMENT_EMPLOYMENT_SPECIFY_NUMBER', 'LAND_ACQ_PROPOSAL', 'text', 'Involvement of employment, if any (Specify Number of employments and conditional employments)', NULL, NULL, '{ "acqModeId": [1, 2, 6] }'::jsonb, NULL, NULL, 1, true, 380, 'रोजगार की भागीदारी, यदि कोई हो (रोजगार और सशर्त रोजगार की संख्या निर्दिष्ट करें)'),
('REPORT_EXAMINATION_PROPOSAL_AREA', 'LAND_ACQ_PROPOSAL', 'document', 'Report on examination of the proposal by the Area Land Cell Committee and recommendation thereof', NULL, NULL, '{ "acqModeId": [6, 2, 1] }'::jsonb, NULL, NULL, 1, true, 390, 'क्षेत्रीय भूमि सेल समिति द्वारा प्रस्ताव की जांच पर रिपोर्ट और उस पर सिफारिश'),
('REVENUE_PLAN_SHOWING_BOUNDARY', 'LAND_ACQ_PROPOSAL', 'document', 'A revenue plan showing the boundary of the approved/ authorized project/ working area, important surface features, land owned by ECL, Government land, Patta Land, Forest land and area of land to be acquired for the workings as well as other ancill...', 'A revenue plan showing the boundary of the approved/ authorized project/ working area, important surface features, land owned by ECL, Government land, Patta Land, Forest land and area of land to be acquired for the workings as well as other ancillary activities approved for the project/ mine washed in different colors and all details mentioned in Activity step 1.2.A(d)', NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 400, 'स्वीकृत/अधिकृत परियोजना/कार्य क्षेत्र, महत्वपूर्ण सतही विशेषताओं, ईसीएल के स्वामित्व वाली भूमि, सरकारी भूमि, पट्टा भूमि, वन भूमि और परियोजना/खदान के लिए अनुमोदित अन्य सहायक गतिविधियों के लिए अधिग्रहित की जाने वाली भूमि के क्षेत्र को विभिन्न रंगों में दर्शाने वाला एक राजस्व मानचित्र (विवरण गतिविधि चरण 1.2.A(d) में उल्लिखित)'),
('LAND_DATA_HAS_BEEN', 'LAND_ACQ_PROPOSAL', 'boolean', 'Whether the land data has been authenticated by the concerned authorities of District revenue department', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 410, 'क्या जिला राजस्व विभाग के संबंधित अधिकारियों द्वारा भूमि डेटा को प्रमाणित किया गया है'),
('FILLED_UP_STANDARD_FORMAT', 'LAND_ACQ_PROPOSAL', 'document', 'Filled up standard format of questionnaire duly signed by the Competent Authority (Area General Manager)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 420, 'सक्षम प्राधिकारी (क्षेत्रीय महाप्रबंधक) द्वारा विधिवत हस्ताक्षरित प्रश्नावली का भरा हुआ मानक प्रारूप'),
('NOTI_SEC_7_3', 'LAND_ACQ_PROPOSAL', 'document', 'Detailed plan, as per revenue records with schedule, showing the total area to be notified under section 7(1), in which the area notified under section 4(1) should also be clearly indicated in different colour. The scale of the plan shall be RF 1 ...', 'Detailed plan, as per revenue records with schedule, showing the total area to be notified under section 7(1), in which the area notified under section 4(1) should also be clearly indicated in different colour. The scale of the plan shall be RF 1 : 4000 scale (1 cm = 40 meters). (Five copies of plan to be sent in physical mode)', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 430, 'राजस्व अभिलेखों के अनुसार विस्तृत योजना और अनुसूची, जिसमें धारा 7(1) के तहत अधिसूचित किए जाने वाले कुल क्षेत्र को दर्शाया गया हो, जिसमें धारा 4(1) के तहत अधिसूचित क्षेत्र को भी अलग रंग में स्पष्ट रूप से इंगित किया जाना चाहिए। योजना का पैमाना RF 1:4000 (1 सेमी = 40 मीटर) होगा। (योजना की पांच प्रतियां भौतिक रूप में भेजी जानी हैं)'),
('NOTI_SEC_7_4', 'LAND_ACQ_PROPOSAL', 'document', 'A proposed draft notification under Section 7(1) of the CBA Act in respect of the coal block/ area in English and in Hindi (both hard copy as well as soft copy). (Specimen of the draft notification is given at Format No. 2D).', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 440, 'कोयला ब्लॉक/क्षेत्र के संबंध में सीबीए (CBA) अधिनियम की धारा 7(1) के तहत अंग्रेजी और हिंदी में प्रस्तावित मसौदा अधिसूचना (हार्ड कॉपी और सॉफ्ट कॉपी दोनों)। (मसौदा अधिसूचना का नमूना प्रारूप संख्या 2D पर दिया गया है)।'),
('CERTIFICATE_CONFIRMING_THAT_AREA', 'LAND_ACQ_PROPOSAL', 'document', 'Certificate confirming that the area proposed to be notified has not been leased out to any other person or party by the State Government / Central Government for any other purpose. (Specimen of the certificate is given at Format No. 1B).', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 450, 'प्रमाणपत्र जो यह पुष्टि करता है कि अधिसूचित किए जाने वाले प्रस्तावित क्षेत्र को राज्य सरकार/केंद्र सरकार द्वारा किसी अन्य उद्देश्य के लिए किसी अन्य व्यक्ति या पार्टी को पट्टे पर नहीं दिया गया है। (प्रमाणपत्र का नमूना प्रारूप संख्या 1B पर दिया गया है)।'),
('CERTIFICATE_CONFIRMING_THAT_AREA_1', 'LAND_ACQ_PROPOSAL', 'document', 'Certificate confirming that the area proposed to be notified has not been leased out to any other person or party by the State Government / Central Government for any other purpose. (Specimen of the certificate is given at Format No. 1B)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 460, 'प्रमाणपत्र जो यह पुष्टि करता है कि अधिसूचित किए जाने वाले प्रस्तावित क्षेत्र को राज्य सरकार/केंद्र सरकार द्वारा किसी अन्य उद्देश्य के लिए किसी अन्य व्यक्ति या पार्टी को पट्टे पर नहीं दिया गया है। (प्रमाणपत्र का नमूना प्रारूप संख्या 1B पर दिया गया है)।'),
('CERTIFICATE_INDICATING_THAT_SUFFICIENT', 'LAND_ACQ_PROPOSAL', 'document', 'Certificate indicating that sufficient coal is available in the area proposed to be notified. A copy of the relevant exploration report may be enclosed. (Specimen of the certificate is given at Format No. 2A)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 470, 'प्रमाणपत्र जो यह इंगित करता है कि अधिसूचित किए जाने वाले प्रस्तावित क्षेत्र में पर्याप्त कोयला उपलब्ध है। प्रासंगिक अन्वेषण रिपोर्ट की एक प्रति संलग्न की जा सकती है। (प्रमाणपत्र का नमूना प्रारूप संख्या 2A पर दिया गया है)'),
('PROSPECTING_TIME_EXTENDED_THEN', 'LAND_ACQ_PROPOSAL', 'boolean', 'If the prospecting time is extended, then the notification indicating the same may also be submitted.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 480, 'यदि पूर्वेक्षण (prospecting) का समय बढ़ाया गया है, तो उसी को इंगित करने वाली अधिसूचना भी प्रस्तुत की जा सकती है।'),
('REHABILITATION_PAFS_INVOLVED_THEN', 'LAND_ACQ_PROPOSAL', 'boolean', 'If the Rehabilitation of PAFs is involved then he will take immediate actions as per the approved ''Rehabilitation Planning Guideline'' or in the absence of the same for preparation and consent with respect to ''Scheme for Rehabilitation'' as describe...', 'If the Rehabilitation of PAFs is involved then he will take immediate actions as per the approved ''Rehabilitation Planning Guideline'' or in the absence of the same for preparation and consent with respect to ''Scheme for Rehabilitation'' as described in Activity Step- 8 of the SOP.', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 490, 'यदि PAFs का पुनर्वास शामिल है, तो वह अनुमोदित ''पुनर्वास योजना दिशानिर्देश'' के अनुसार या इसकी अनुपस्थिति में एसओपी के गतिविधि चरण-8 में वर्णित ''पुनर्वास के लिए योजना'' की तैयारी और सहमति के लिए तत्काल कार्रवाई करेगा।'),
('WILL_ENTRUST_SUITABLE_OFFICIALS', 'LAND_ACQ_PROPOSAL', 'boolean', 'Will entrust suitable officials of his Area for collection of data and information regarding ownership of the lands and getting the same authenticated by the concerned authorities of the District revenue department.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 500, 'भूमि के स्वामित्व के संबंध में डेटा और जानकारी एकत्र करने और जिला राजस्व विभाग के संबंधित अधिकारियों द्वारा इसे प्रमाणित करवाने के लिए अपने क्षेत्र के उपयुक्त अधिकारियों को सौंपेंगे।'),
('NOTI_SEC_7_5', 'LAND_ACQ_PROPOSAL', 'boolean', 'Submit all documents like a detailed schedule of plots for acquisition, a Copy of relevant pages of the Project Report/ Scheme, a Copy of the Geological report, and Five copies of Mouza maps showing specified areas in different mouzas that has bee...', 'Submit all documents like a detailed schedule of plots for acquisition, a Copy of relevant pages of the Project Report/ Scheme, a Copy of the Geological report, and Five copies of Mouza maps showing specified areas in different mouzas that has been proposed for acquisition statements and certificates in prescribed Form 2A, 2B, 2C, 2D etc. and Any other document which will be needed for notification under Section 7 of the Act. (Care should be taken to complete this step as early as possible because the maximum time allowed between notification u/s 4 and 7 is Two Years. Central Government may extend this period up to further one year).', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 510, 'अधिग्रहण के लिए भूखंडों की विस्तृत अनुसूची, परियोजना रिपोर्ट/योजना के प्रासंगिक पृष्ठों की प्रति, भूवैज्ञानिक रिपोर्ट की प्रति, और विभिन्न मौजा में निर्दिष्ट क्षेत्रों को दर्शाने वाले मौजा मानचित्रों की पांच प्रतियां जो अधिग्रहण विवरण और निर्धारित प्रपत्र 2A, 2B, 2C, 2D आदि में प्रमाण पत्र और कोई अन्य दस्तावेज जो अधिनियम की धारा 7 के तहत अधिसूचना के लिए आवश्यक होगा, जैसे सभी दस्तावेज जमा करें। (इस चरण को जल्द से जल्द पूरा करने के लिए सावधानी बरती जानी चाहिए क्योंकि धारा 4 और 7 के तहत अधिसूचना के बीच अधिकतम अनुमत समय दो वर्ष है। केंद्र सरकार इस अवधि को आगे एक वर्ष तक बढ़ा सकती है)।'),
('PUBLISH_CONTENT_NOTIFICATION_U', 'LAND_ACQ_PROPOSAL', 'boolean', 'Publish the content of Notification u/s 7 along with the schedule of land on the website of the company and in two newspapers, one in well-circulated English daily and one in well-circulated local vernacular.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 520, 'धारा 7 के तहत अधिसूचना की सामग्री को भूमि की अनुसूची के साथ कंपनी की वेबसाइट पर और दो समाचार पत्रों में, एक अच्छी तरह से प्रसारित अंग्रेजी दैनिक में और एक अच्छी तरह से प्रसारित स्थानीय भाषा के समाचार पत्र में प्रकाशित करें।'),
('SEND_WRITTEN_REQUESTS_GENERAL', 'LAND_ACQ_PROPOSAL', 'boolean', 'Send written requests to General Manager (P&P) and General Manager (Systems) attaching the required plan and other information like latitude/ longitude of the acquired land including the settlements/ villages that lie within the area of acquisitio...', 'Send written requests to General Manager (P&P) and General Manager (Systems) attaching the required plan and other information like latitude/ longitude of the acquired land including the settlements/ villages that lie within the area of acquisition for capturing Satellite images of the same area.', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 530, 'महाप्रबंधक (P&P) और महाप्रबंधक (सिस्टम) को लिखित अनुरोध भेजें, जिसमें आवश्यक योजना और अन्य जानकारी जैसे अधिग्रहित भूमि का अक्षांश/देशांतर, जिसमें अधिग्रहण क्षेत्र के भीतर स्थित बस्तियां/गांव शामिल हैं, संलग्न करें ताकि उसी क्षेत्र की सैटेलाइट तस्वीरें ली जा सकें।'),
('PUBLISH_CONTENT_NOTIFICATION_U_1', 'LAND_ACQ_PROPOSAL', 'boolean', 'Publish the content of Notification u/s 11 along with the schedule of land as notified u/s 9 on the website of the company and in two newspapers, one in well-circulated English daily and one in well-circulated local vernacular.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 540, 'धारा 11 के तहत अधिसूचना की सामग्री को धारा 9 के तहत अधिसूचित भूमि की अनुसूची के साथ कंपनी की वेबसाइट पर और दो समाचार पत्रों में, एक अच्छी तरह से प्रसारित अंग्रेजी दैनिक में और एक अच्छी तरह से प्रसारित स्थानीय भाषा के समाचार पत्र में प्रकाशित करें।'),
('REHABILITATION_PAFS_AREA_GENERAL', 'LAND_ACQ_PROPOSAL', 'boolean', 'For Rehabilitation of PAFs Area General Manager will also take steps for constitution of the Resettlement & Rehabilitation Committee as described in Activity Step- 8.B.6 of the SOP.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 550, 'PAFs के पुनर्वास के लिए क्षेत्रीय महाप्रबंधक एसओपी के गतिविधि चरण- 8.B.6 में वर्णित अनुसार पुनर्वास एवं पुनर्व्यवस्थापन समिति के गठन के लिए भी कदम उठाएंगे।'),
('SPECIFIC_PROPOSAL_STATING_PURPOSE', 'LAND_ACQ_PROPOSAL', 'document', 'Specific proposal stating purpose, justification and detailing with respect to acquisition of land', NULL, NULL, '{ "acqModeId": [6, 2] }'::jsonb, NULL, NULL, 1, true, 560, 'भूमि अधिग्रहण के संबंध में उद्देश्य, औचित्य और विवरण बताते हुए विशिष्ट प्रस्ताव'),
('SPECIFIC_PROPOSAL_STATING_PURPOSE_1', 'LAND_ACQ_PROPOSAL', 'document', 'Specific proposal stating purpose, justification and detailing with respect to
acquisition of land', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 570, 'भूमि अधिग्रहण के संबंध में उद्देश्य, औचित्य और विवरण बताते हुए विशिष्ट प्रस्ताव'),
('REVENUE_PLAN_SHOWING_BOUNDARY_1', 'LAND_ACQ_PROPOSAL', 'document', 'A revenue plan showing the boundary of the approved/ authorized project/ working area, important surface features, land owned by ECL, Government land, Patta Land, Forest land and area of land to be acquired for the workings as well as other ancill...', 'A revenue plan showing the boundary of the approved/ authorized project/ working area, important surface features, land owned by ECL, Government land, Patta Land, Forest land and area of land to be acquired for the workings as well as other ancillary activities approved for the project/ mine washed in different colours.', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 580, 'स्वीकृत/अधिकृत परियोजना/कार्य क्षेत्र, महत्वपूर्ण सतही विशेषताओं, ईसीएल के स्वामित्व वाली भूमि, सरकारी भूमि, पट्टा भूमि, वन भूमि और परियोजना/खदान के लिए अनुमोदित अन्य सहायक गतिविधियों के लिए अधिग्रहित की जाने वाली भूमि के क्षेत्र को विभिन्न रंगों में दर्शाने वाला एक राजस्व मानचित्र।'),
('REVENUE_PLAN_SHOWING_BOUNDARY_2', 'LAND_ACQ_PROPOSAL', 'document', 'A revenue plan showing the boundary of the approved/ authorized project/ working area, important surface features, land owned by ECL, Government land, Patta Land, Forest land and area of land to be acquired for the workings as well as other ancill...', 'A revenue plan showing the boundary of the approved/ authorized project/ working area, important surface features, land owned by ECL, Government land, Patta Land, Forest land and area of land to be acquired for the workings as well as other ancillary activities approved for the project/ mine washed in different colors.', NULL, '{ "acqModeId": [2] }'::jsonb, NULL, NULL, 1, true, 590, 'स्वीकृत/अधिकृत परियोजना/कार्य क्षेत्र, महत्वपूर्ण सतही विशेषताओं, ईसीएल के स्वामित्व वाली भूमि, सरकारी भूमि, पट्टा भूमि, वन भूमि और परियोजना/खदान के लिए अनुमोदित अन्य सहायक गतिविधियों के लिए अधिग्रहित की जाने वाली भूमि के क्षेत्र को विभिन्न रंगों में दर्शाने वाला एक राजस्व मानचित्र।'),
('TECHNO_ECONOMIC_REPORT_SHOWING', 'LAND_ACQ_PROPOSAL', 'document', 'Techno-Economic Report showing estimated total financial involvement and capital involvement for cost of land acquisition, rehabilitation and employment for land', NULL, NULL, '{ "acqModeId": [1, 2] }'::jsonb, NULL, NULL, 1, true, 600, 'तकनीकी-आर्थिक रिपोर्ट (Techno-Economic Report) जिसमें भूमि अधिग्रहण, पुनर्वास और भूमि के बदले रोजगार की लागत के लिए अनुमानित कुल वित्तीय भागीदारी और पूंजी भागीदारी दिखाई गई हो'),
('TECHNO_ECONOMIC_REPORT_SHOWING_1', 'LAND_ACQ_PROPOSAL', 'document', 'Techno-Economic Report showing estimated total financial involvement and capital involvement for cost of land acquisition, rehabilitation and employment for land.', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 610, 'तकनीकी-आर्थिक रिपोर्ट (Techno-Economic Report) जिसमें भूमि अधिग्रहण, पुनर्वास और भूमि के बदले रोजगार की लागत के लिए अनुमानित कुल वित्तीय भागीदारी और पूंजी भागीदारी दिखाई गई हो'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATIO_4', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Tenancy land like copies of agreement with landowners/ previous settlement of compensation, minutes of meeting with landowners, Government certified market value etc. for current land or chron...', 'Documents to substantiate the rates of compensation of Tenancy land like copies of agreement with landowners/ previous settlement of compensation, minutes of meeting with landowners, Government certified market value etc. for current land or chronologically nearest previous case of possession of land', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 620, 'किरायेदारी (Tenancy) भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे भूस्वामियों के साथ समझौते की प्रतियां/मुआवजे का पिछला निपटान, भूस्वामियों के साथ बैठक का कार्यवृत्त, वर्तमान भूमि या भूमि के कब्जे के कालानुक्रमिक रूप से निकटतम पिछले मामले के लिए सरकार द्वारा प्रमाणित बाजार मूल्य आदि।'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATIO_5', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Tenancy land like copies of agreements with landowners/ previous settlement of compensation, minutes of meeting with landowners, Government certified market value etc. for current land or chro...', 'Documents to substantiate the rates of compensation of Tenancy land like copies of agreements with landowners/ previous settlement of compensation, minutes of meeting with landowners, Government certified market value etc. for current land or chronologically nearest previous case of possession of land', NULL, '{ "acqModeId": [2] }'::jsonb, NULL, NULL, 1, true, 630, 'किरायेदारी (Tenancy) भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे भूस्वामियों के साथ समझौते की प्रतियां/मुआवजे का पिछला निपटान, भूस्वामियों के साथ बैठक का कार्यवृत्त, वर्तमान भूमि या भूमि के कब्जे के कालानुक्रमिक रूप से निकटतम पिछले मामले के लिए सरकार द्वारा प्रमाणित बाजार मूल्य आदि।'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATIO_6', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Government land/ Patta Land like the copy of Government certified market value/ demand of District Authority etc.', NULL, NULL, '{ "acqModeId": [2] }'::jsonb, NULL, NULL, 1, true, 640, 'सरकारी भूमि/पट्टा भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे सरकार द्वारा प्रमाणित बाजार मूल्य की प्रति/जिला प्राधिकरण की मांग आदि।'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATIO_7', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Forest land like copies of demands of the State Forest department etc.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 650, 'वन भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे राज्य वन विभाग की मांग की प्रतियां आदि।'),
('CALCULATION_SHEET_SHOWING_COST_2', 'LAND_ACQ_PROPOSAL', 'document', 'Calculation sheet showing the cost of acquisition of all types of land including cost of registration and mutation.', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 660, 'पंजीकरण और दाखिल-खारिज की लागत सहित सभी प्रकार की भूमि के अधिग्रहण की लागत दर्शाने वाला गणना पत्रक।'),
('DOCUMENTS_SUBSTANTIATE_RATES_COMPENSATIO_8', 'LAND_ACQ_PROPOSAL', 'document', 'Documents to substantiate the rates of compensation of Tenancy land like copies of agreements with landowners etc. for current land or rates approved for similar types of lands in the same/ nearby mine in recent past.', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 670, 'किरायेदारी भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे भूस्वामियों के साथ समझौतों की प्रतियां आदि वर्तमान भूमि के लिए या हाल के दिनों में उसी/निकटवर्ती खदान में समान प्रकार की भूमि के लिए स्वीकृत दरें।'),
('COPY_AUTHENTIC_DOCUMENT_SHOWING', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of authentic document showing the situation of the project/ mine (For ascertaining the rate of processing fees for mutation)', NULL, NULL, '{ "acqModeId": [6] }'::jsonb, NULL, NULL, 1, true, 680, 'परियोजना/खदान की स्थिति दर्शाने वाले प्रामाणिक दस्तावेज की प्रति (दाखिल-खारिज के लिए प्रसंस्करण शुल्क की दर का पता लगाने के लिए)'),
('COPY_NOTIFICATION_UNDER_SECTION', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of Notification under section 4', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 690, 'धारा 4 के तहत अधिसूचना की प्रति'),
('NOTI_SEC_11_3', 'LAND_ACQ_PROPOSAL', 'document', 'Copy of Notification under section 11', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 700, 'धारा 11 के तहत अधिसूचना की प्रति'),
('COPIES_PLAN_SHOWING_BLOCK', 'LAND_ACQ_PROPOSAL', 'document', 'Copies of plan showing the block area with village boundaries and village schedule to be notified at 1” = 1 miles or 1” = 2 miles scale, considering block size in A3 size paper.', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 710, 'ब्लॉक क्षेत्र को गांव की सीमाओं और अधिसूचित की जाने वाली ग्राम अनुसूची के साथ 1” = 1 मील या 1” = 2 मील के पैमाने पर, A3 आकार के कागज में ब्लॉक के आकार को ध्यान में रखते हुए दर्शाने वाले नक्शे की प्रतियां।'),
('CERTIFICATE_CONFIRMING_THAT_COAL', 'LAND_ACQ_PROPOSAL', 'document', 'Certificate confirming that coal is likely to be found in the area proposed to be notified and the basis of such assumption with documentary evidence/reports etc. (Specimen of the certificate is given at Format No.1A)', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 720, 'प्रमाणपत्र जो यह पुष्टि करता है कि अधिसूचित किए जाने वाले प्रस्तावित क्षेत्र में कोयला मिलने की संभावना है और दस्तावेजी साक्ष्य/रिपोर्ट आदि के साथ ऐसी धारणा का आधार। (प्रमाणपत्र का नमूना प्रारूप संख्या 1A पर दिया गया है)'),
('PROPOSED_DRAFT_NOTIFICATION_UNDER', 'LAND_ACQ_PROPOSAL', 'document', 'A proposed draft notification under Section 4(1) of the CBA Act in respect of the coal block/ area in English and in Hindi (both hard copy as well as soft copy). (Specimen of the draft notification, both English and Hindi version is given at Forma...', 'A proposed draft notification under Section 4(1) of the CBA Act in respect of the coal block/ area in English and in Hindi (both hard copy as well as soft copy). (Specimen of the draft notification, both English and Hindi version is given at Format No. 1D).', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 730, 'कोयला ब्लॉक/क्षेत्र के संबंध में सीबीए अधिनियम की धारा 4(1) के तहत अंग्रेजी और हिंदी में प्रस्तावित मसौदा अधिसूचना (हार्ड कॉपी और सॉफ्ट कॉपी दोनों)। (अंग्रेजी और हिंदी दोनों संस्करणों के मसौदा अधिसूचना का नमूना प्रारूप संख्या 1D पर दिया गया है)।'),
('NOTI_SEC_9_3', 'LAND_ACQ_PROPOSAL', 'document', 'A proposed draft notification under Section 9(1) of the CBA Act in respect of the coal block/ area in English and in Hindi (both hard copy as well as soft copy). (Specimen of the draft notification is given at Format No . 3A).', NULL, NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 740, 'कोयला ब्लॉक/क्षेत्र के संबंध में सीबीए अधिनियम की धारा 9(1) के तहत अंग्रेजी और हिंदी में प्रस्तावित मसौदा अधिसूचना (हार्ड कॉपी और सॉफ्ट कॉपी दोनों)। (मसौदा अधिसूचना का नमूना प्रारूप संख्या 3A पर दिया गया है)।'),
('NOTI_SEC_7_6', 'LAND_ACQ_PROPOSAL', 'document', 'Detailed plan as per revenue records with a schedule showing the total area to be notified under section 9(1), in which the area notified under section 7(1) should also be clearly indicated in different color. The scale of the plan shall be RF 1 :...', 'Detailed plan as per revenue records with a schedule showing the total area to be notified under section 9(1), in which the area notified under section 7(1) should also be clearly indicated in different color. The scale of the plan shall be RF 1 : 4000 scale (1 cm = 40 meters). (Five copies of plan to be sent in physical mode)', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 750, 'राजस्व अभिलेखों के अनुसार विस्तृत योजना एक अनुसूची के साथ जिसमें धारा 9(1) के तहत अधिसूचित किए जाने वाले कुल क्षेत्र को दर्शाया गया हो, जिसमें धारा 7(1) के तहत अधिसूचित क्षेत्र को भी अलग रंग में स्पष्ट रूप से इंगित किया जाना चाहिए। योजना का पैमाना RF 1:4000 (1 सेमी = 40 मीटर) होगा। (योजना की पांच प्रतियां भौतिक रूप में भेजी जानी हैं)'),
('UPLOAD_COPY_NOTICES_REGARDING', 'LAND_ACQ_PROPOSAL', 'document', 'Upload copy of notices regarding content of Notification u/s 11 along with the schedule of land as notified u/s 9 as published on the website of the company and in two newspapers, one in well-circulated English daily and one in well-circulated loc...', 'Upload copy of notices regarding content of Notification u/s 11 along with the schedule of land as notified u/s 9 as published on the website of the company and in two newspapers, one in well-circulated English daily and one in well-circulated local vernacular.', NULL, '{ "acqModeId": [1] }'::jsonb, NULL, NULL, 1, true, 760, 'कंपनी की वेबसाइट पर और दो समाचार पत्रों में, एक अच्छी तरह से प्रसारित अंग्रेजी दैनिक और एक अच्छी तरह से प्रसारित स्थानीय भाषा में प्रकाशित धारा 9 के तहत अधिसूचित भूमि की अनुसूची के साथ धारा 11 के तहत अधिसूचना की सामग्री के संबंध में नोटिस की प्रति अपलोड करें।')
